mapper.select:
SELECT sc.*, s.name AS student_name, co.course_name, co.credit

WHERE sc.stu_id = #{stuId}
  AND sc.course_id = #{courseId}
  AND sc.semester = #{semester}
  AND sc.exam_type = #{examType}

SELECT sc.*, s.name AS student_name, co.course_name, co.credit,
       c.class_name, m.major_name, d.dept_name
FROM Score sc
JOIN Student s ON sc.stu_id = s.stu_id
JOIN Course co ON sc.course_id = co.course_id
JOIN Class c ON s.class_id = c.class_id
JOIN Major m ON c.major_id = m.major_id
JOIN Department d ON m.dept_id = d.dept_id


        AND sc.stu_id LIKE #{stuId}


        AND s.name LIKE #{stuName}


        AND co.course_name LIKE #{courseName}


        AND sc.semester LIKE #{semester}


        AND d.dept_id = #{deptId}


        AND m.major_id = #{majorId}


        AND c.class_id = #{classId}


ORDER BY sc.semester DESC, sc.stu_id

mapper.update:
UPDATE Score SET score = #{score}
WHERE stu_id = #{stuId} AND course_id = #{courseId}
  AND semester = #{semester} AND exam_type = #{examType}

mapper.delete:
DELETE FROM Score
WHERE stu_id = #{stuId} AND course_id = #{courseId}
  AND semester = #{semester} AND exam_type = #{examType}
